import{_ as a}from"./chunks/model-link-setting-01.CpWihLl4.js";import{_ as r}from"./chunks/model-link-setting-02.2A_MOACW.js";import{_ as i}from"./chunks/model-link-setting-03.CnGpaE4C.js";import{_ as e}from"./chunks/model-link-setting-04.D0WRcZQ8.js";import{_ as o}from"./chunks/model-setting-01.B6pLEcOa.js";import{_ as s,a as n,b as l,c as d,d as p,e as g,f as c,g as h}from"./chunks/reply-images-setting-05.BOgot54n.js";import{_ as u,o as f,c as m,a3 as _}from"./chunks/framework.D1iekJsc.js";const b="/ultra_guides/shots/model-link-setting-International-01.png",A="/ultra_guides/shots/model-link-setting-International-02.png",v="/ultra_guides/shots/model-setting-02.png",w=JSON.parse('{"title":"模型连接与参数","description":"MiniTavern BYOK 模型连接教程：填写 Base URL 与 API Key、测连、采样参数；对接云端或 Ollama/LM Studio 本地 OpenAI 兼容接口。","frontmatter":{"title":"模型连接与参数","description":"MiniTavern BYOK 模型连接教程：填写 Base URL 与 API Key、测连、采样参数；对接云端或 Ollama/LM Studio 本地 OpenAI 兼容接口。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"模型连接与参数 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern BYOK 模型连接教程：填写 Base URL 与 API Key、测连、采样参数；对接云端或 Ollama/LM Studio 本地 OpenAI 兼容接口。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/manual/model-link"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/manual/model-link"}]]},"headers":[],"relativePath":"manual/model-link.md","filePath":"manual/model-link.md","lastUpdated":1787814812000}'),I={name:"manual/model-link.md"};function y(T,t,k,P,x,q){return f(),m("div",null,[...t[0]||(t[0]=[_('<h1 id="模型连接与参数" tabindex="-1">模型连接与参数 <a class="header-anchor" href="#模型连接与参数" aria-label="Permalink to &quot;模型连接与参数&quot;">​</a></h1><p>BYOK：密钥保存在本机安全存储；请求直连你配置的地址。</p><p>没有付费 API 时，可先看 <a href="/ultra_guides/free-cloud/">免费云端</a>；本机部署见 <a href="/ultra_guides/local/">部署本地模型</a>。</p><p>设置首页 <strong>AI 相关</strong>分为三个入口（文案以 App 为准）：</p><table tabindex="0"><thead><tr><th>设置首页入口</th><th>Hub 子项</th><th>作用</th></tr></thead><tbody><tr><td><strong>模型</strong></td><td>模型连接、模型设置</td><td>对话 API 与全局采样</td></tr><tr><td><strong>生图</strong></td><td>生图连接、生图设置、关键词触发生图</td><td>出图 API、回复图片与规则</td></tr><tr><td><strong>聊天设置</strong></td><td>识图设置、聊天显示</td><td>图片描写、气泡显示等</td></tr></tbody></table><p>单聊覆盖路径：<strong>聊天页 → 聊天设置 → 语言模型 / 生图模型 / 识图与显示</strong>（不改全局默认）。</p><h2 id="模型连接" tabindex="-1">模型连接 <a class="header-anchor" href="#模型连接" aria-label="Permalink to &quot;模型连接&quot;">​</a></h2><p>路径：<strong>设置 → 模型 → 模型连接</strong></p><div class="shot-flow"><figure class="shot-step"><img src="'+a+'" alt="模型连接入口"><figcaption>1 · 进入模型连接</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="新建连接"><figcaption>2 · 选择模型链接</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="填写表单"><figcaption>3 · 填平台、密钥与模型</figcaption></figure><figure class="shot-step"><img src="'+e+'" alt="测连成功"><figcaption>4 · 测连成功</figcaption></figure></div><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>新建</td><td>平台、密钥、Base URL、模型</td></tr><tr><td>编辑 / 复制 / 删除</td><td>列表右侧菜单</td></tr><tr><td>设为默认</td><td>新对话默认使用</td></tr><tr><td>测连</td><td>保存前或编辑页「测试」。须选<strong>文本聊天</strong>模型；TTS / 生图专用 ID（如 Gemini <code>*-tts</code>）会报不支持文字对话，见 <a href="./errors#textoutputunsupported">错误排错 · textOutputUnsupported</a></td></tr></tbody></table><h3 id="平台类型-常见" tabindex="-1">平台类型（常见） <a class="header-anchor" href="#平台类型-常见" aria-label="Permalink to &quot;平台类型（常见）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项（文案以 App 为准）</th><th>用途</th></tr></thead><tbody><tr><td>各云厂商预设</td><td>自动填国内/国际站 Base URL</td></tr><tr><td>自定义 (OpenAI 协议)</td><td>本地 Ollama / LM Studio、兼容网关</td></tr><tr><td>自定义 Gemini / Anthropic</td><td>对应协议端点</td></tr></tbody></table><h3 id="多站点-·-国际站" tabindex="-1">多站点 · 国际站 <a class="header-anchor" href="#多站点-·-国际站" aria-label="Permalink to &quot;多站点 · 国际站&quot;">​</a></h3><p>部分平台（如智谱、百炼等）支持中国站与国际站，密钥归属需与所选站点一致。</p><div class="shot-flow"><figure class="shot-step"><img src="'+b+'" alt="国际站提示"><figcaption>1 · 切换国际站</figcaption></figure><figure class="shot-step"><img src="'+A+'" alt="使用国际站"><figcaption>2 · 测连成功</figcaption></figure></div><p>本地模型详见 <a href="/ultra_guides/connect-app/minitavern">连接 MiniTavern</a> 与 <a href="/ultra_guides/local/tools">工具总览</a>。</p><h2 id="模型设置-全局参数" tabindex="-1">模型设置（全局参数） <a class="header-anchor" href="#模型设置-全局参数" aria-label="Permalink to &quot;模型设置（全局参数）&quot;">​</a></h2><p>路径：<strong>设置 → 模型 → 模型设置</strong></p><div class="shot-flow"><figure class="shot-step"><img src="'+o+'" alt="模型设置上屏"><figcaption>1 · 选择模型设置</figcaption></figure><figure class="shot-step"><img src="'+v+'" alt="模型设置下屏"><figcaption>2 · 模型参数配置</figcaption></figure></div><p>常见项（名称以 App 为准）：</p><ul><li>记忆长度（历史条数相关）</li><li>回复令牌（max tokens，上限 128000；部分 Claude 场景<strong>不要</strong>设为 None）</li><li>Temperature、Top-P / Top-K</li><li>是否流式输出</li></ul><h2 id="会话级覆盖" tabindex="-1">会话级覆盖 <a class="header-anchor" href="#会话级覆盖" aria-label="Permalink to &quot;会话级覆盖&quot;">​</a></h2><p>路径：对话页 → <strong>聊天设置</strong> → <strong>语言模型</strong></p><p>可为单聊指定连接与采样，不改全局默认。</p><h2 id="识图-图片描写" tabindex="-1">识图（图片描写） <a class="header-anchor" href="#识图-图片描写" aria-label="Permalink to &quot;识图（图片描写）&quot;">​</a></h2><p>路径：<strong>设置 → 聊天设置 → 识图设置</strong></p><div class="shot-flow"><figure class="shot-step"><img src="'+s+'" alt="进入识图设置"><figcaption>1 · 设置页选择聊天设置</figcaption></figure><figure class="shot-step"><img src="'+n+'" alt="图片描写开关"><figcaption>2 · 选择识图设置</figcaption></figure><figure class="shot-step"><img src="'+l+'" alt="描写模型与提示词"><figcaption>3 · 描写模型与提示词</figcaption></figure></div><p>单聊可在 <strong>聊天设置 → 识图与显示</strong> 跟随默认或单独覆盖（描写模型与提示词仍用全局）。</p><ul><li>关闭「图片描写」：多模态直接把图送给模型（模型需支持视觉）。</li><li>开启：仅当当前聊天主模型<strong>不支持</strong>图片参数时生效——先由描写模型图转文（可与识人同一次请求），再发主模型；描写结果会缓存复用。主模型已支持视觉时仍多模态直传，此开关不拦截。</li></ul><p>不支持图片的主模型 + 开启描写后的发送顺序：描写（+识人）→ 主聊天（若开了智能/关键词回复出图会附带生图提示词）→ 若回复带生图数据再旁路生图。</p><p>若报「当前模型不支持图片」，见 <a href="./errors#visionunsupported">错误排错 · visionUnsupported</a>。</p><h2 id="生图-连接-回复图片-关键词" tabindex="-1">生图（连接 / 回复图片 / 关键词） <a class="header-anchor" href="#生图-连接-回复图片-关键词" aria-label="Permalink to &quot;生图（连接 / 回复图片 / 关键词）&quot;">​</a></h2><p>路径：<strong>设置 → 生图 → 生图设置</strong>（回复图片在生图设置页内）</p><div class="shot-flow"><figure class="shot-step"><img src="'+d+'" alt="进入生图设置"><figcaption>1 · 设置页选择生图</figcaption></figure><figure class="shot-step"><img src="'+p+'" alt="回复图片开关"><figcaption>2 · 生图设置</figcaption></figure><figure class="shot-step"><img src="'+g+'" alt="触发方式"><figcaption>3 · 生图模型连接配置</figcaption></figure><figure class="shot-step"><img src="'+c+'" alt="画质与数量"><figcaption>4 · 回复图片与生图配置</figcaption></figure><figure class="shot-step"><img src="'+h+'" alt="提示词模板"><figcaption>5 · 回复图片关键词</figcaption></figure></div><table tabindex="0"><thead><tr><th>子页</th><th>说明</th></tr></thead><tbody><tr><td><strong>生图连接</strong></td><td>添加与管理生图 API（<strong>设置 → 生图 → 生图连接</strong>）</td></tr><tr><td><strong>生图设置</strong></td><td>尺寸/质量、生成数量（仅 <code>/imagine</code>）、增强/负面提示词；<strong>回复图片</strong>开关与触发方式</td></tr><tr><td><strong>关键词触发生图</strong></td><td>规则列表；需同时在生图设置里开启回复图片并选关键词模式</td></tr></tbody></table><p><strong>回复图片</strong>（在生图设置里）：先打开开关，再选触发方式。关闭后聊天不会自动出图（斜杠命令、附件菜单、长按气泡不受影响）</p><ul><li><strong>智能判断</strong>：由模型根据对话判断这一轮要不要出图；画幅按场景选（手机自拍 3:4，相机成片 3:2），命中后固定 1 张。可附图发送作风格参考</li><li><strong>关键词触发</strong>：用户消息命中关键词规则时出图；画面和画幅按当前对话生成，命中后 1 张</li></ul><p>聊天里生图：</p><table tabindex="0"><thead><tr><th>入口</th><th>说明</th></tr></thead><tbody><tr><td><code>/imagine 提示词</code></td><td>先经主聊天模型判断：是否与当前对话有关、要不要角色/用户参考图，再拼提示词去生图。可先点加号附图。张数用生图设置里的「生成数量」。失败时气泡会留下并显示重试</td></tr><tr><td><code>/imagine scene</code> / 附件 → 根据故事</td><td>按近期对话画当前这一幕，1 张</td></tr><tr><td><code>/imagine last</code> / 附件 → 根据最后消息</td><td>按最后一条消息来画，1 张</td></tr></tbody></table><p>未配置生图连接时，附件菜单四种生图模式与发送 <code>/imagine</code> 会弹出「去设置 / 取消」，不清空输入框。智能 / 关键词自动出图则为 Toast。在生图设置开启「回复图片」时若无连接会弹窗，开关保持关闭。</p><p>| 附件 → 生成背景图 | 画环境背景，1 张；完成后可设为聊天背景 | | 长按气泡 → 生图 | 按这条气泡来画，1 张 |</p><p>例子：输入「给我一张你的自拍照」会带上角色参考和对话语境；「给我一张小狗的照片」则按独立请求画，不套角色脸。</p><p>本机 A1111 / ComfyUI：<a href="/ultra_guides/local/image-gen/">生图模型部署</a> · <a href="/ultra_guides/local/image-gen/connect-app">连 App</a>。<br> 云端免费档见 <a href="/ultra_guides/free-cloud/#免费生图怎么配">免费云端 · 生图</a>。</p><h2 id="排错入口" tabindex="-1">排错入口 <a class="header-anchor" href="#排错入口" aria-label="Permalink to &quot;排错入口&quot;">​</a></h2><p>测连或聊天失败 → Toast / 气泡 → <strong>查看详情</strong>（错误代码 + 原因 + 建议）→ 对照 <a href="./errors">错误代码排错</a>。</p>',45)])])}const R=u(I,[["render",y]]);export{w as __pageData,R as default};
